package com.keevo.inventory.counting.domain.port.in;

import java.util.Map;
import java.util.UUID;

/**
 * Command encapsulating the intent to validate an inventory session.
 * GoF Command pattern — pure data object, no behavior.
 * Story 6.4.
 *
 * @param movementIds ADJUSTMENT movement ids generated by an offline device, keyed by
 *                    {@link #movementKey(UUID, UUID)}. Reusing them lets the pull upsert the
 *                    device's own movement rows instead of adding a second copy. Empty online.
 */
public record ValidateInventoryCommand(UUID sessionId, UUID actorId, Map<String, UUID> movementIds) {

    public ValidateInventoryCommand {
        movementIds = movementIds != null ? Map.copyOf(movementIds) : Map.of();
    }

    public ValidateInventoryCommand(UUID sessionId, UUID actorId) {
        this(sessionId, actorId, Map.of());
    }

    /** Key of a counted product line: "productId|variantId" (empty variant when none). */
    public static String movementKey(UUID productId, UUID variantId) {
        return productId + "|" + (variantId != null ? variantId : "");
    }
}
